Repair the complete CommonJS source below and return a corrected complete source file exporting exactly `{ planViewport }`. `planViewport(rowHeights, scrollTop, viewportHeight)` accepts an array of finite non-negative row heights plus finite non-negative scroll and viewport values. Reject malformed values with `TypeError` and do not mutate the array. Clamp `scrollTop` to the total height. Return `{ first, lastExclusive, totalHeight, top }`. For a positive viewport, use half-open geometry: a row ending exactly at `top` is not visible, while a row beginning below `top + viewportHeight` is within the returned contiguous range. Zero-height rows at or before `top` are skipped. For a zero-height viewport, return an empty range at the first row whose bottom is greater than `top`. At the content bottom, or for an empty array, the range begins and ends at `rowHeights.length`.

Known-bad source:
'use strict';

function planViewport(rowHeights, scrollTop, viewportHeight) {
  if (!Array.isArray(rowHeights) || rowHeights.some(value => !Number.isFinite(value) || value < 0) ||
      !Number.isFinite(scrollTop) || scrollTop < 0 ||
      !Number.isFinite(viewportHeight) || viewportHeight < 0) {
    throw new TypeError('invalid viewport');
  }

  const totalHeight = rowHeights.reduce((sum, value) => sum + value, 0);
  const top = Math.min(scrollTop, totalHeight);
  let first = 0;
  let cursor = 0;
  while (first < rowHeights.length && cursor + rowHeights[first] < top) {
    cursor += rowHeights[first];
    first += 1;
  }

  if (viewportHeight === 0 || first === rowHeights.length) {
    return { first, lastExclusive: first, totalHeight, top };
  }

  const limit = Math.min(totalHeight, top + viewportHeight);
  let lastExclusive = first;
  while (lastExclusive < rowHeights.length && cursor < limit) {
    cursor += rowHeights[lastExclusive];
    lastExclusive += 1;
  }

  return { first, lastExclusive, totalHeight, top };
}

module.exports = { planViewport };

