'use strict';
const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api), ['planViewport']);
const { planViewport } = api;

assert.deepStrictEqual(planViewport([], 0, 10), {
  first: 0, lastExclusive: 0, totalHeight: 0, top: 0
});
assert.deepStrictEqual(planViewport([10, 20, 30], 0, 15), {
  first: 0, lastExclusive: 2, totalHeight: 60, top: 0
});
assert.deepStrictEqual(planViewport([10, 20, 30], 10, 20), {
  first: 1, lastExclusive: 2, totalHeight: 60, top: 10
});
assert.deepStrictEqual(planViewport([10, 20, 30], 15, 1), {
  first: 1, lastExclusive: 2, totalHeight: 60, top: 15
});
assert.deepStrictEqual(planViewport([10, 20, 30], 100, 10), {
  first: 3, lastExclusive: 3, totalHeight: 60, top: 60
});
assert.deepStrictEqual(planViewport([10, 20, 30], 60, 0), {
  first: 3, lastExclusive: 3, totalHeight: 60, top: 60
});

assert.deepStrictEqual(planViewport([0, 5, 0, 5], 0, 5), {
  first: 1, lastExclusive: 2, totalHeight: 10, top: 0
});
assert.deepStrictEqual(planViewport([0, 5, 0, 5], 2, 4), {
  first: 1, lastExclusive: 4, totalHeight: 10, top: 2
});
assert.deepStrictEqual(planViewport([0, 5, 0, 5], 5, 1), {
  first: 3, lastExclusive: 4, totalHeight: 10, top: 5
});
assert.deepStrictEqual(planViewport([0, 5, 0, 5], 0, 0), {
  first: 1, lastExclusive: 1, totalHeight: 10, top: 0
});
assert.deepStrictEqual(planViewport([0, 5, 0, 5], 5, 0), {
  first: 3, lastExclusive: 3, totalHeight: 10, top: 5
});
assert.deepStrictEqual(planViewport([0, 0], 0, 10), {
  first: 2, lastExclusive: 2, totalHeight: 0, top: 0
});

const heights = [4, 6];
const snapshot = heights.slice();
planViewport(heights, 3, 4);
assert.deepStrictEqual(heights, snapshot);

for (const args of [
  [null, 0, 1],
  [[1, -1], 0, 1],
  [[1, NaN], 0, 1],
  [[1, Infinity], 0, 1],
  [[1, '2'], 0, 1],
  [[1], -1, 1],
  [[1], NaN, 1],
  [[1], Infinity, 1],
  [[1], 0, -1],
  [[1], 0, NaN],
  [[1], 0, Infinity]
]) assert.throws(() => planViewport(args[0], args[1], args[2]), TypeError);

